    private int i;

    public Node expTree(String s) {
        this.s = s;
        this.i = 0;
        return expr();
    }

    private Node expr() {
        Node node = term();
        while (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
            Node op = new Node(s.charAt(i++));
            op.left = node;
            op.right = term();
            node = op;
        }
        return node;
    }

    private Node term() {
        Node node = factor();
        while (i < s.length() && (s.charAt(i) == '*' || s.charAt(i) == '/')) {
            Node op = new Node(s.charAt(i++));
            op.left = node;
            op.right = factor();
            node = op;
        }
        return node;
    }

    private Node factor() {
        if (s.charAt(i) == '(') {
            i++;
            Node node = expr();
            i++;
            return node;
