class Solution {
public:
    Node* expTree(string s) {
        unordered_map<char, int> prec{{'+', 1}, {'-', 1}, {'*', 2}, {'/', 2}, {'(', 0}};
        vector<Node*> nodes;
        vector<char> ops;
        auto combine = [&]() {
            char op = ops.back(); ops.pop_back();
            Node* r = nodes.back(); nodes.pop_back();
            Node* l = nodes.back(); nodes.pop_back();
            nodes.push_back(new Node(op, l, r));
        };
        for (char c : s) {
            if (isdigit(c)) {
                nodes.push_back(new Node(c));
            } else if (c == '(') {
                ops.push_back(c);
            } else if (c == ')') {
                while (ops.back() != '(') combine();
                ops.pop_back();
            } else {
                while (!ops.empty() && prec[ops.back()] >= prec[c]) combine();
                ops.push_back(c);
            }
        }
        while (!ops.empty()) combine();
        return nodes.back();
    }
};

