class Solution {
    public Node expTree(String s) {
        Map<Character, Integer> prec = Map.of('+', 1, '-', 1, '*', 2, '/', 2, '(', 0);
        Deque<Node> nodes = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                nodes.push(new Node(c));
            } else if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (ops.peek() != '(') reduce(nodes, ops);
                ops.pop();
            } else {
                while (!ops.isEmpty() && prec.get(ops.peek()) >= prec.get(c)) reduce(nodes, ops);
                ops.push(c);
            }
        }
        while (!ops.isEmpty()) reduce(nodes, ops);
        return nodes.peek();
    }

    private void reduce(Deque<Node> nodes, Deque<Character> ops) {
        char op = ops.pop();
        Node right = nodes.pop(), left = nodes.pop();
        nodes.push(new Node(op, left, right));
    }
}

