    const nodes = [], ops = [];
    const combine = () => {
        const op = ops.pop();
        const r = nodes.pop(), l = nodes.pop();
        nodes.push(new Node(op, l, r));
    };
    for (const c of s) {
        if (c >= '0' && c <= '9') {
            nodes.push(new Node(c));
