            ops.push(c);
        } else if (c === ')') {
            while (ops[ops.length - 1] !== '(') combine();
            ops.pop();
        } else {
            while (ops.length && prec[ops[ops.length - 1]] >= prec[c]) combine();
            ops.push(c);
        }
    }
    while (ops.length) combine();
    return nodes[nodes.length - 1];
};
